jQuery.noConflict();

jQuery(function ($) {
    // Footer copyright year
    $("#current-year").text(new Date().getFullYear());

    // Full-screen mobile offcanvas menu
    const $menu = $("#headerMenu");
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

    if ($menu.length) {
        const desktop = window.matchMedia("(min-width: 62rem)"); // 992px
        const viewportHeight = CSS.supports("height", "100dvh") ? "100dvh" : "100vh";

        $menu
            .removeClass("offcanvas-start offcanvas-end offcanvas-bottom")
            .addClass("offcanvas-top");

        function updateMenu() {
            const mobile = !desktop.matches;

            $menu.css({
                height: mobile ? viewportHeight : "",
                maxHeight: mobile ? "none" : "",
                transitionProperty: mobile ? "transform" : "",
                transitionDuration: mobile ? (reducedMotion.matches ? "0ms" : "450ms") : "",
                transitionTimingFunction: mobile ? "ease-in-out" : ""
            });
        }

        updateMenu();
        desktop.addEventListener("change", updateMenu);
        reducedMotion.addEventListener("change", updateMenu);
    }

    // Builder controls and UTM field mapping
    const $form = $("#builderForm");

    if (!$form.length) {
        return;
    }

    const $destination = $("#destination");
    const $campaignLink = $("#campaignLink");
    const $copyLink = $("#copyLink");
    const $status = $("<div>", { role: "status" }).insertAfter($copyLink);
    const $example = $("#heroExample");
    const $exampleStatus = $("<div>", { role: "status" }).insertAfter($example);

    const parameters = {
        source: "utm_source",
        medium: "utm_medium",
        campaign: "utm_campaign",
        campaignId: "utm_id",
        term: "utm_term",
        content: "utm_content"
    };

    $copyLink.prop("disabled", true);

    // Clear the generated link when any campaign field changes.
    function clearResult() {
        $campaignLink.val("");
        $copyLink.prop("disabled", true);
        $status.empty();
    }

    $form.on("input", clearResult);

    // Generate a campaign URL and preserve unrelated query parameters and the fragment.
    $form.on("submit", function (event) {
        event.preventDefault();
        clearResult();

        let url;

        try {
            url = new URL($destination.val().trim());

            if (url.protocol !== "https:" && url.protocol !== "http:") {
                throw new Error("Unsupported URL protocol");
            }
        } catch {
            $status.text("Enter a full website address starting with https:// or http://.");
            $destination.trigger("focus");
            return;
        }

        $.each(parameters, function (field, parameter) {
            const value = $(`#${field}`).val().trim();

            if (value) {
                url.searchParams.set(parameter, value);
            } else {
                url.searchParams.delete(parameter);
            }
        });

        $campaignLink.val(url.href);
        $copyLink.prop("disabled", false);
        $status.text("Your campaign link is ready to copy.");
    });

    // Copy the generated campaign link.
    $copyLink.on("click", async function () {
        const link = $campaignLink.val();

        if (!link) {
            return;
        }

        try {
            await navigator.clipboard.writeText(link);
            $status.text("Campaign link copied.");
        } catch {
            $campaignLink[0].select();
            $status.text("Copy was unavailable. The link is selected so you can copy it manually.");
        }
    });

    // Fetch the newsletter example, fill the form, and generate its link.
    $example.on("click", async function (event) {
        event.preventDefault();
        $example.prop("disabled", true);
        $exampleStatus.text("Loading example…");

        try {
            const response = await fetch("./data/utm-example.json");

            if (!response.ok) {
                throw new Error(`Example request failed (${response.status})`);
            }

            const example = await response.json();

            $destination.val(example.destination);

            $.each(parameters, function (field) {
                $(`#${field}`).val(example[field] ?? "");
            });

            $("#builderDetails").prop("open", false);
            $form[0].requestSubmit();
            $("#builder")[0].scrollIntoView({
                behavior: reducedMotion.matches ? "instant" : "smooth"
            });
            $exampleStatus.empty();
        } catch {
            $exampleStatus.text("The example could not load. Please try again.");
        } finally {
            $example.prop("disabled", false);
        }
    });
});